// The DSA indexer's prefill logits on gfx950, 32 heads of 128 over contiguous fp8 keys, in place:
// logits[r, c] = kv_scales[c] * sum_h weights[r, h] * relu(q[r, h] . kv[c]) for c in [cu_starts[r],
// cu_ends[r]); the rest of each row is left as it is. A block holds 16 rows, four a wave, their queries in
// registers, and its waves walk the same 64-key groups, so a group's keys come from L1 for three of them;
// a wave walks only the groups its own rows' windows reach. A group is four 16 x 16 x 128 fp8 MFMA tiles
// a head half, tile b's column c being key 4c + b. Each row's scores go through relu into f16 and an
// f16 MFMA against the row's weights sums the heads, so that lane c of the first lane group ends with
// keys 4c .. 4c + 3 of the wave's four rows.
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <ATen/hip/impl/HIPGuardImplMasqueradingAsCUDA.h>
#include <c10/hip/HIPException.h>
#include <hip/hip_runtime.h>
#include <torch/library.h>

namespace mqa_logits {
namespace {

constexpr int HEADS    = 32;
constexpr int HEAD_DIM = 128;
constexpr int ROWS     = 4;  // rows a wave scores, one per lane group after the head sum
constexpr int WAVES    = 4;
constexpr int BLOCK    = ROWS * WAVES;
constexpr int GROUP    = 64;  // keys a wave scores per step
constexpr int TILES    = 4;   // 16-key MFMA tiles of a group

typedef int   i32x4 __attribute__((ext_vector_type(4)));
typedef int   i32x8 __attribute__((ext_vector_type(8)));
typedef float f32x4 __attribute__((ext_vector_type(4)));
typedef _Float16 f16x2 __attribute__((ext_vector_type(2)));
typedef _Float16 f16x8 __attribute__((ext_vector_type(8)));
typedef short    i16x2 __attribute__((ext_vector_type(2)));

union V8 {
    i32x8 v;
    i32x4 h[2];
};

struct Params {
    const uint8_t *q;       // [n_q, HEADS, HEAD_DIM] e4m3
    const uint8_t *k;       // [n_k, HEAD_DIM] e4m3
    const float   *scales;  // [n_k]
    const float   *w;       // [n_q, HEADS]
    const int     *starts;  // [n_q]
    const int     *ends;    // [n_q]
    float         *out;     // [n_q, n_cols]
    int            n_q;
    int            n_k;
    int            n_cols;
    int            splits;  // blocks along a row block's window
};

struct Group {
    V8    k[TILES];
    f32x4 scale;
};

// S_EXP: scores come out of the fp8 MFMA times 2^-S_EXP (q's block scale), so that the largest an e4m3
// product sum can be, 448^2 * 128 < 2^25, stays within f16
constexpr int S_EXP = 10;
// W_EXP: a row's weights go to f16 times 2^(W_EXP - e), e the exponent of the largest one
constexpr int W_EXP = 14;

__device__ __forceinline__ f32x4 mfma(i32x8 a, i32x8 b) {
    const f32x4 zero = {0.f, 0.f, 0.f, 0.f};
    // e4m3 operands; q's block scale 2^-S_EXP, the keys' 1
    return __builtin_amdgcn_mfma_scale_f32_16x16x128_f8f6f4(a, b, zero, 0, 0, 0, 127 - S_EXP, 0, 127);
}

// relu of two scores as f16: negative f16 are negative as int16
__device__ __forceinline__ f16x2 relu_f16(float a, float b) {
    const i16x2 h = __builtin_bit_cast(i16x2, __builtin_amdgcn_cvt_pkrtz(a, b));
    return __builtin_bit_cast(f16x2, __builtin_elementwise_max(h, (i16x2){0, 0}));
}

// 32 bytes of a row: lane (g, c)'s operand bytes [32g, 32g + 32)
__device__ __forceinline__ void load32(const uint8_t *src, V8 &d) {
    d.h[0] = *reinterpret_cast<const i32x4 *>(src);
    d.h[1] = *reinterpret_cast<const i32x4 *>(src + 16);
}

__device__ __forceinline__ void load_group(const Params &p, int g, int lane, Group &d) {
    const int c = lane & 15, part = lane >> 4, last = p.n_k - 1;
    const int key0 = g * GROUP + 4 * c;
#pragma unroll
    for (int b = 0; b < TILES; ++b)
        load32(p.k + static_cast<size_t>(min(key0 + b, last)) * HEAD_DIM + part * 32, d.k[b]);
    if (key0 + 3 <= last)
        d.scale = *reinterpret_cast<const f32x4 *>(p.scales + key0);
    else
#pragma unroll
        for (int b = 0; b < TILES; ++b) d.scale[b] = p.scales[min(key0 + b, last)];
}

struct Rows {
    V8    qa[ROWS], qb[ROWS];
    f32x4 wa[ROWS], wb[ROWS];
    int   rs[ROWS], re[ROWS];  // the rows' windows, wave-uniform
};

// one group: per row, its eight score MFMAs, their relu in f16 as the B operand of an f16 MFMA whose A is
// the row's weights in row r alone, so that tile b's sum over the heads lands in D_b's row r: lane group 0
// holds rows 0 .. 3 at keys 4c + b, and stores them inside each row's window
__device__ __forceinline__ void score_group(const Rows &w, const f16x8 (&wa)[ROWS], const Group &k, int g, int lane,
                                            float *out0, size_t n_cols, const float (&back)[ROWS], int lo_e, int hi_s,
                                            int live) {
    const int c = lane & 15;
    f32x4     d[TILES];
#pragma unroll
    for (int b = 0; b < TILES; ++b) d[b] = (f32x4){0.f, 0.f, 0.f, 0.f};
    // row r + 1's score MFMAs issued before row r's relu and reduction
    f32x4 x[2][TILES][2];
#pragma unroll
    for (int b = 0; b < TILES; ++b) {
        x[0][b][0] = mfma(w.qa[0].v, k.k[b].v);
        x[0][b][1] = mfma(w.qb[0].v, k.k[b].v);
    }
#pragma unroll
    for (int r = 0; r < ROWS; ++r) {
        if (r + 1 < ROWS) {
#pragma unroll
            for (int b = 0; b < TILES; ++b) {
                x[(r + 1) & 1][b][0] = mfma(w.qa[r + 1].v, k.k[b].v);
                x[(r + 1) & 1][b][1] = mfma(w.qb[r + 1].v, k.k[b].v);
            }
        }
#pragma unroll
        for (int b = 0; b < TILES; ++b) {
            const f32x4 x0 = x[r & 1][b][0], x1 = x[r & 1][b][1];
            // k = 8 part + j: heads 4 part + j of the first half, then 16 + 4 part + j - 4
            const f16x2 h0 = relu_f16(x0[0], x0[1]), h1 = relu_f16(x0[2], x0[3]);
            const f16x2 h2 = relu_f16(x1[0], x1[1]), h3 = relu_f16(x1[2], x1[3]);
            const f16x8 bv = {h0[0], h0[1], h1[0], h1[1], h2[0], h2[1], h3[0], h3[1]};
            d[b]           = __builtin_amdgcn_mfma_f32_16x16x32_f16(wa[r], bv, d[b], 0, 0, 0);
        }
    }
    if (lane >= 16) return;
    const int key0 = g * GROUP + 4 * c;
    f32x4     v[ROWS];
#pragma unroll
    for (int r = 0; r < ROWS; ++r) {
#pragma unroll
        for (int b = 0; b < TILES; ++b) v[r][b] = d[b][r] * k.scale[b];
        v[r] *= back[r];
    }
    // every live row's window holds the whole group: no masks; rows past n_q have no window
    if (g * GROUP >= hi_s && (g + 1) * GROUP <= lo_e) {
#pragma unroll
        for (int r = 0; r < ROWS; ++r)
            if (r < live) *reinterpret_cast<f32x4 *>(out0 + r * n_cols + key0) = v[r];
        return;
    }
#pragma unroll
    for (int r = 0; r < ROWS; ++r)
#pragma unroll
        for (int b = 0; b < TILES; ++b)
            if (key0 + b >= w.rs[r] && key0 + b < w.re[r]) out0[r * n_cols + key0 + b] = v[r][b];
}

__global__ __launch_bounds__(WAVES * 64) void logits_kernel(Params p) {
    const int lane = threadIdx.x & 63, part = lane >> 4, c = lane & 15;
    const int wave = __builtin_amdgcn_readfirstlane(threadIdx.x >> 6);
    // the last rows first: causal windows grow with the row, so the longest walks start first
    const int row0 = (gridDim.x - 1 - blockIdx.x) * BLOCK;
    // the block's joint window: lane r < 16 reads row row0 + r
    int lo = INT_MAX, hi = 0;
    if (lane < BLOCK && row0 + lane < p.n_q) {
        const int s = max(p.starts[row0 + lane], 0), e = min(p.ends[row0 + lane], p.n_k);
        if (e > s) lo = s, hi = e;
    }
    for (int o = 1; o < BLOCK; o <<= 1) {
        lo = min(lo, __shfl_xor(lo, o));
        hi = max(hi, __shfl_xor(hi, o));
    }
    lo = __builtin_amdgcn_readfirstlane(lo);
    hi = __builtin_amdgcn_readfirstlane(hi);
    if (hi <= lo) return;
    // this block's share of the window's groups
    const int g0 = lo / GROUP, groups = (hi + GROUP - 1) / GROUP - g0;
    const int per = (groups + p.splits - 1) / p.splits;
    const int gb = g0 + min(groups, per * static_cast<int>(blockIdx.y));
    const int ge = g0 + min(groups, per * static_cast<int>(blockIdx.y + 1));
    if (gb >= ge) return;

    // the wave's rows: queries and weights of all four in every lane, windows wave-uniform
    const int r_base = row0 + wave * ROWS;
    Rows      w;
#pragma unroll
    for (int r = 0; r < ROWS; ++r) {
        const int  row  = min(r_base + r, p.n_q - 1);
        const bool live = r_base + r < p.n_q;
        load32(p.q + (static_cast<size_t>(row) * HEADS + c) * HEAD_DIM + part * 32, w.qa[r]);
        load32(p.q + (static_cast<size_t>(row) * HEADS + 16 + c) * HEAD_DIM + part * 32, w.qb[r]);
        w.wa[r] = *reinterpret_cast<const f32x4 *>(p.w + static_cast<size_t>(row) * HEADS + 4 * part);
        w.wb[r] = *reinterpret_cast<const f32x4 *>(p.w + static_cast<size_t>(row) * HEADS + 16 + 4 * part);
        // a window cut to the keys, as aiter cuts it
        w.rs[r] = __builtin_amdgcn_readfirstlane(live ? max(p.starts[row], 0) : 0);
        w.re[r] = __builtin_amdgcn_readfirstlane(live ? min(p.ends[row], p.n_k) : 0);
    }
    // the wave's joint window, cut to this block's share
    int wlo = INT_MAX, whi = 0;
#pragma unroll
    for (int r = 0; r < ROWS; ++r)
        if (w.re[r] > w.rs[r]) wlo = min(wlo, w.rs[r]), whi = max(whi, w.re[r]);
    const int wgb = max(gb, wlo / GROUP), wge = min(ge, (whi + GROUP - 1) / GROUP);
    if (wgb >= wge) return;
    // each row's weights in f16, times 2^(W_EXP - e_r), as the A operand of its reduction MFMA: lane
    // (part, m) holds row m's k = 8 part .. 8 part + 7 for m == r, else 0
    f16x8 wa[ROWS];
    float back[ROWS];
#pragma unroll
    for (int r = 0; r < ROWS; ++r) {
        float m = 0.f;
#pragma unroll
        for (int i = 0; i < 4; ++i) m = __builtin_fmaxf(m, __builtin_fmaxf(__builtin_fabsf(w.wa[r][i]), __builtin_fabsf(w.wb[r][i])));
        m = __builtin_fmaxf(m, __shfl_xor(m, 16));
        m = __builtin_fmaxf(m, __shfl_xor(m, 32));
        const int   e  = m > 0.f ? __builtin_amdgcn_frexp_expf(m) : 0;
        const float up = __builtin_ldexpf(1.f, W_EXP - e);
        back[r]        = __builtin_ldexpf(1.f, S_EXP + e - W_EXP);
        const bool mine = c == r;
#pragma unroll
        for (int i = 0; i < 4; ++i) {
            wa[r][i]     = mine ? static_cast<_Float16>(w.wa[r][i] * up) : static_cast<_Float16>(0.f);
            wa[r][4 + i] = mine ? static_cast<_Float16>(w.wb[r][i] * up) : static_cast<_Float16>(0.f);
        }
    }
    float *out0 = p.out + static_cast<size_t>(r_base) * p.n_cols;
    // the keys every live row's window holds; rows past n_q have none
    const int live = min(ROWS, p.n_q - r_base);
    int       lo_e = INT_MAX, hi_s = 0;
#pragma unroll
    for (int r = 0; r < ROWS; ++r)
        if (r_base + r < p.n_q) lo_e = min(lo_e, w.re[r]), hi_s = max(hi_s, w.rs[r]);

    // two groups' keys in flight: one scored while the next loads
    Group a, b;
    load_group(p, wgb, lane, a);
    for (int g = wgb; g < wge; g += 2) {
        if (g + 1 < wge) load_group(p, g + 1, lane, b);
        score_group(w, wa, a, g, lane, out0, p.n_cols, back, lo_e, hi_s, live);
        if (g + 1 >= wge) break;
        if (g + 2 < wge) load_group(p, g + 2, lane, a);
        score_group(w, wa, b, g + 1, lane, out0, p.n_cols, back, lo_e, hi_s, live);
    }
}

void run(const at::Tensor &q, const at::Tensor &kv, const at::Tensor &kv_scales, const at::Tensor &weights,
         const at::Tensor &cu_starts, const at::Tensor &cu_ends, at::Tensor &logits, at::Tensor &no_values) {
    TORCH_CHECK(q.size(1) == HEADS && q.size(2) == HEAD_DIM && kv.size(1) == HEAD_DIM, "32 heads of 128 only");
    TORCH_CHECK(logits.size(0) == q.size(0) && logits.size(1) >= kv.size(0), "a row of logits per query, a column per key");
    TORCH_CHECK(q.is_contiguous() && kv.is_contiguous() && kv_scales.is_contiguous() && weights.is_contiguous() &&
                    cu_starts.is_contiguous() && cu_ends.is_contiguous() && logits.is_contiguous(),
                "contiguous tensors only");
    const at::hip::OptionalHIPGuardMasqueradingAsCUDA guard(q.device());
    Params p{};
    p.q      = static_cast<const uint8_t *>(q.data_ptr());
    p.k      = static_cast<const uint8_t *>(kv.data_ptr());
    p.scales = kv_scales.data_ptr<float>();
    p.w      = weights.data_ptr<float>();
    p.starts = cu_starts.data_ptr<int>();
    p.ends   = cu_ends.data_ptr<int>();
    p.out    = logits.data_ptr<float>();
    p.n_q    = static_cast<int>(q.size(0));
    p.n_k    = static_cast<int>(kv.size(0));
    p.n_cols = static_cast<int>(logits.size(1));
    if (p.n_q == 0) return;
    const int cus    = at::cuda::getCurrentDeviceProperties()->multiProcessorCount;
    const int blocks = (p.n_q + BLOCK - 1) / BLOCK;
    // enough blocks for four a CU, a split keeping at least 8 groups
    const int max_split = std::max(1, (p.n_k + GROUP * 8 - 1) / (GROUP * 8));
    p.splits            = std::min(max_split, std::max(1, (4 * cus + blocks - 1) / blocks));
    hipLaunchKernelGGL(logits_kernel, dim3(blocks, p.splits), dim3(WAVES * 64), 0, at::hip::getCurrentHIPStream(), p);
    C10_HIP_CHECK(hipGetLastError());
}

} // namespace
} // namespace mqa_logits

#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
    m.def("run(Tensor q, Tensor kv, Tensor kv_scales, Tensor weights, Tensor cu_starts, Tensor cu_ends, "
          "Tensor(a!) logits, Tensor(b!) no_values) -> ()",
          &mqa_logits::run);
}
